                v !== "" &&
                (!Number.isFinite(Number(v)) || Math.abs(Number(v)) > 1e12)) ||
              (types[c] === "fecha" &&
                v !== "" &&
                (!/^\d{4}-\d{2}-\d{2}$/.test(v) ||
                  !Number.isFinite(Date.parse(v)) ||
                  new Date(v).toISOString().slice(0, 10) !== v)),
          ),
        )
