          const view = {
            name,
            query,
            sorts,
            columnOrder,
            pinned: [...pinned],
            widths: headers.map(h => h.style.width),
            group: form.elements.grupo?.value || "",
            search: form.elements.buscar?.value || "",
            state: form.elements.estado?.value || "",
            hidden: [
