      el.classList.add("explorer-ready");
      el.dataset.presentation = "auto";
      const box = el.querySelector(".tabla-caja");
      const scrollHint = make("p", "Desliza la tabla para ver más columnas →");
      scrollHint.className = "explorer-scroll-hint";
